:root{
  --bg:#07111e; --bg-card:#0d1b2e; --bg-card2:#12233a; --border:#1f3555;
  --accent:#7c9eff; --accent-dim:#4b628f; --text:#e6edf7; --text-dim:#c7d6ec; --text-faint:#9cb0cf;
  --ok:#5fd4a0; --warn:#ffcf6e; --sidebar-w:300px;
  --font:"Noto Sans JP","Noto Sans CJK JP","Hiragino Kaku Gothic ProN","Yu Gothic",Meiryo,sans-serif;
  --mono:ui-monospace,SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;overflow-x:hidden}
body{margin:0;background:var(--bg);color:var(--text);font-family:var(--font);font-size:16px;line-height:1.85;overflow-x:hidden}
.layout{display:block}
.sidebar{position:fixed;top:0;left:0;bottom:0;width:var(--sidebar-w);background:var(--bg-card);border-right:1px solid var(--border);overflow-y:auto;padding:24px 16px 40px;z-index:20}
.sidebar .brand{font-size:12px;letter-spacing:.08em;color:var(--accent);font-weight:700;margin:0 8px 14px;text-transform:uppercase}
.sidebar ul{list-style:none;margin:0;padding:0}
.sidebar li>ul{margin:2px 0 8px 12px;border-left:1px solid var(--border)}
.sidebar a{display:block;color:var(--text-dim);text-decoration:none;font-size:13.5px;line-height:1.5;padding:6px 10px;border-radius:6px}
.sidebar li>ul a{font-size:12.5px;color:var(--text-faint)}
.sidebar a:hover{background:var(--bg-card2);color:#fff}
.sidebar a.active{background:rgba(124,158,255,.16);color:#fff;box-shadow:inset 3px 0 0 var(--accent)}
.toggle{display:none;position:fixed;top:12px;left:12px;z-index:30;background:var(--bg-card2);color:var(--text);border:1px solid var(--border);border-radius:8px;padding:8px 12px;font:inherit;font-size:14px;cursor:pointer}
.main{margin-left:var(--sidebar-w);padding:40px 48px 80px}
.hero{position:relative;background:var(--bg-card);border:1px solid var(--border);border-radius:16px;padding:32px 32px 24px;margin-bottom:36px;overflow:hidden}
.hero::before{content:"";position:absolute;top:-120px;right:-80px;width:340px;height:340px;background:radial-gradient(circle,rgba(124,158,255,.28),transparent 70%);pointer-events:none}
.eyebrow{display:inline-block;font-size:12px;font-weight:700;color:var(--accent);background:rgba(124,158,255,.14);border:1px solid rgba(124,158,255,.35);border-radius:999px;padding:4px 14px;margin-bottom:14px;position:relative}
.hero-title{margin:0 0 20px;font-size:28px;font-weight:800;color:#fff;line-height:1.45;position:relative}
.hero-meta{display:flex;flex-wrap:wrap;border-top:1px solid var(--border);padding-top:16px;position:relative}
.meta-item{display:flex;flex-direction:column;gap:2px;padding:4px 24px 4px 0;margin-right:24px;border-right:1px solid var(--border);min-width:0}
.meta-item:last-child{border-right:0;margin-right:0}
.meta-label{font-size:11px;letter-spacing:.06em;color:var(--text-faint);text-transform:uppercase}
.meta-value{font-size:14.5px;color:var(--text);overflow-wrap:anywhere}
h2{font-size:24px;font-weight:800;color:#fff;margin:56px 0 18px;padding:0 0 10px;border-bottom:1px solid var(--border);scroll-margin-top:20px;line-height:1.5}
h3{font-size:19px;font-weight:700;color:var(--accent);margin:34px 0 12px;scroll-margin-top:20px;line-height:1.5}
p{margin:0 0 16px}
ul,ol{margin:0 0 16px;padding-left:1.4em}
li{margin:4px 0}
a{color:var(--accent);overflow-wrap:anywhere}
strong{color:#fff;font-weight:700}
hr{border:0;border-top:1px solid var(--border);margin:32px 0}
code{font-family:var(--mono);font-size:.88em;background:var(--bg-card2);border:1px solid var(--border);border-radius:5px;padding:1px 6px;color:#ffd6a5;overflow-wrap:anywhere}
pre{background:#050d18;border:1px solid var(--border);border-radius:10px;padding:16px 18px;overflow-x:auto;margin:0 0 20px;line-height:1.65}
pre code{background:none;border:0;padding:0;color:var(--text);font-size:13.5px;overflow-wrap:normal}
.tok-k{color:#7c9eff;font-weight:700}.tok-s{color:#8fe3b0}.tok-c{color:#6f86aa;font-style:italic}.tok-n{color:#ffcf6e}
.table-scroll{overflow-x:auto;margin:0 0 22px;border:1px solid var(--border);border-radius:10px;background:var(--bg-card)}
table{border-collapse:collapse;width:100%;font-size:14.5px;min-width:520px}
th{background:var(--bg-card2);color:#fff;text-align:left;font-weight:700;padding:10px 14px;border-bottom:1px solid var(--border);white-space:nowrap}
td{padding:10px 14px;border-bottom:1px solid var(--border);vertical-align:top;color:var(--text-dim)}
tr:last-child td{border-bottom:0}
tbody tr:hover td{background:rgba(124,158,255,.05)}
td a{word-break:break-all}
.callout{border:1px solid var(--border);border-left:4px solid var(--accent);background:var(--bg-card);border-radius:10px;padding:14px 18px;margin:0 0 22px}
.callout p:last-child{margin-bottom:0}
.callout-practice{border-left-color:var(--ok)}
.callout-warn{border-left-color:var(--warn)}
.mermaid-diagram{display:block;overflow-x:auto;background:var(--bg-card);border:1px solid var(--border);border-radius:12px;padding:20px;margin:0 0 24px}
.mermaid-diagram svg{display:block;margin-left:auto;margin-right:auto;max-width:none;flex-shrink:0}
.mermaid-diagram p{color:inherit;margin:0}
.page-footer{margin-top:64px;padding-top:20px;border-top:1px solid var(--border);color:var(--text-faint);font-size:13px}
@media (max-width:960px){
  .sidebar{transform:translateX(-100%);transition:transform .2s}
  .sidebar.open{transform:none;box-shadow:0 0 40px rgba(0,0,0,.6)}
  .toggle{display:block}
  .main{margin-left:0;padding:64px 18px 60px}
  .hero{padding:24px 20px 18px}.hero-title{font-size:22px}
  .meta-item{border-right:0;border-bottom:1px solid var(--border);width:100%;margin-right:0;padding:8px 0}
  .meta-item:last-child{border-bottom:0}
  h2{font-size:21px}
}
